-- A claim gets the sheet's next number when it is opened: 1, 2, ... with no gaps and never reused.
-- A draft has no number, and voiding a claim clears it. The sheet keeps the last number it gave.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
-- A voided claim now keeps the number it was opened with; the number is still never reused, as the
-- sheet's last_claim_number only grows. Claims voided before this change have no number left to restore.
-- Only a DRAFT claim can be edited; an open claim is voided and added again instead.
SELECT 1;
-- A claim with a negative amount is a correction: it names, by number, the settled claim of the same person it
-- corrects. None for any other claim.
ALTER TABLE claim ADD COLUMN corrects INTEGER;
-- A sheet's policy date: a claim dated before it rounds half up, one dated on or after it half to even. None means
-- the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
