import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';

/** The roles a user name can have on a sheet; any name without one is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type Role = (typeof ROLES)[number];

export interface RoleGiven {
  user: string;
  role: Role;
}

export interface Settings {
  /** The highest due a clerk may settle, with two decimals; null for no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due comes to, with two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** What an overdue claim gains of its figure for every full 30 days overdue, with two decimals. */
  latePct: string;
  /** The date (yyyy-mm-dd) a claim dated before rounds half up, on or after half to even; null for the
   * sheet's today. */
  policyDate: string | null;
}

// A sheet's settings: the role each user name has, its clerk limit, its floor, its terms, its late percent and its policy date, read and changed through the
// server.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  roles(sheetId: string): Observable<RoleGiven[]> {
    return this.http.get<RoleGiven[]>(`${this.url(sheetId)}/roles`, { headers: this.headers() });
  }

  setRole(sheetId: string, user: string, role: string): Observable<RoleGiven> {
    return this.http.put<RoleGiven>(`${this.url(sheetId)}/roles`, { user, role }, { headers: this.headers() });
  }

  get(sheetId: string): Observable<Settings> {
    return this.http.get<Settings>(`${this.url(sheetId)}/settings`, { headers: this.headers() });
  }

  /** Save the settings given; one left out is left as it is. */
  save(
    sheetId: string,
    settings: { clerkLimit?: string; floor?: string; terms?: string; latePct?: string; policyDate?: string },
  ): Observable<Settings> {
    return this.http.put<Settings>(`${this.url(sheetId)}/settings`, settings, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

/** close | soft-close | reopen: true when the period's closed flag changed. */
export async function periodAction(page: Page, name: string, action: string): Promise<boolean> {
  const r = page.getByTestId(`period-row-${name}`);
  const was = await shown(r.getByTestId('period-closed'));
  await r.getByTestId(`period-${action}`).click();
  return until(page, async () => await shown(r.getByTestId('period-closed')) !== was,
    r.getByTestId('period-error'), `period ${action}`);
}

export async function setSetting(page: Page, key: string, value: string): Promise<void> {
  await page.getByTestId(`setting-${key}`).fill(value);
  await page.getByTestId('settings-save').click();
  await expect(page.getByTestId(`setting-${key}-current`)).toHaveText(value);
}

/** Save a setting where the screen may refuse it: true when the value in force shows it. */
export async function setSettingTry(page: Page, key: string, value: string): Promise<boolean> {
  await page.getByTestId(`setting-${key}`).fill(value);
  await page.getByTestId('settings-save').click();
  return until(page, async () => (await shown(page.getByTestId(`setting-${key}-current`))) === value,
    page.getByTestId('settings-error'), 'save setting');
}

